const sizeOf = (d) => (d.length === 4 ? 'year' : d.length === 7 ? 'month' : 'day');
function sourceFor(src, sc) {
  if (src) return src;
  const q = sc && spacecraftById(sc)?.quellen;
  if (!q || !q.length) return null;
  return (q.find((x) => /nssdc\.gsfc\.nasa\.gov/.test(x.url)) || q[0]).url;
}

export const MISSION_EVENTS = RAW.map(([date, title, agency, country, kind, target, status, desc, src, sc], i) => ({
  id: `ev-${i}`,
  date,
  precision: sizeOf(date),
  title, agency, country, kind, target, status, desc,
  source: sourceFor(src, sc),
  sc: sc || null,
})).sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
